      "statement": "P( −1)={a+b −1|a,b∈ 数域 P} 是不是数域？为什么？\nQ( −1),R( −1),C( −1) 分别是什么？\nZ( −1)={m+n −1|m,n∈Z} 是不是数域？为什么？",
