      "source": "陈维新《线性代数》（第二版）1.3 行列式性质，PDF第15页",
      "chapter": "第2章 行列式与矩阵的秩",
      "section": "§2.3  行列式的性质",
      "statement": "求下列多项式的根：\n(1) f(x)=\nx−5 1 −3\n1 x−5 3 ;\n−3 3 x−3\n(2) f(x)=\nx−1 −2 −2\n−2 x−1 −2 ;\n−2 −2 x−1\n(3) f(x)=\n1 a a ⋯ a a\n1 2 n−1 n\n1 x a ⋯ a a\n2 n−1 n\n1 a x ⋯ a a\n1 n−1 n .\n⋮ ⋮ ⋮ ⋮ ⋮\n1 a a ⋯ a x\n1 2 n−1\n(2)",
      "type": "计算题",
