      "chapter": "第1章 线性方程组的求解",
      "section": "§1.2  同解变形与阶梯形线性方程组",
      "statement": "设 $A$ 是 $n$ 阶方阵，且 $|A|\\ne0$。证明：仅用初等行变换可以把 $A$ 化为 $n$ 阶单位矩阵 $I_n$。",
