      "section": "§2.5  矩阵的秩",
      "statement": "设矩阵 A 的秩为 r，问 A 中是否一定存在不为零的 r−1 阶子式？是否存在为零的 r 阶子式？是否存在不\n为零的 r+1 阶子式？",
