      "section": "§4.1  向量组的线性关系",
      "statement": "下列论断哪些是对的，哪些是错的？如果是对的，请证明；否则举出反例： (1) 如果当 k =k =⋯=\n1 2\nk s =0 时，k 1 α 1 +k 2 α 2 +⋯+k s α s =θ，则 α 1 ,α 2 ,⋯ ,α s 线性无关； (2) 若 α 1 ,α 2 ,⋯ ,α s 线性相关，则\n存在不全为零的数 k 1 ,k 2 ,⋯ ,k s，使得 k 1 α 1 +k 2 α 2 +⋯+k s α s =θ； (3) 若 α 1 ,α 2 ,⋯ ,α s 线性无关，\nβ 1 ,β 2 ,⋯ ,β s 线性无关，则 α 1 ,α 2 ,⋯ ,α s ,β 1 ,β 2 ,⋯ ,β s 必线性无关； (4) 若 α 1 ,α 2 ,⋯ ,α s 线性无关，则\n其中每一个向量都不是其余向量的线性组合； (5) 若 α ,α ,⋯ ,α 线性相关，则其中每一个向量都是其余向量\n1 2 s\n的线性组合。\n（2）“相关就存在全不为零的关系系数”：错。取 e ,e ,2e ，任一关系中 e 的系数只能为0。定义要求的是系\n1 2 1 2\n数不全为零。",
