      "chapter": "第4章 n元向量空间",
      "section": "§4.1  向量组的线性关系",
      "statement": "(1) 当复数域 C 作为复数域 C 上线性空间时，问：1,i 是否线性无关？为什么？ (2) 当复数域 C 作为实数\n域 R 上线性空间时，问：1,i 是否线性无关？为什么？",
