      "id": "CWX-4.5-3(1)(3)",
      "source": "陈维新《线性代数》（第二版）4.5 子空间，PDF第58页",
      "chapter": "第4章 n元向量空间",
      "section": "§4.7  子空间",
      "statement": "在线性空间 Pn×n 中，A 是一个取定的 n 阶方阵。 (1) 证明：所有与 A 乘法可换的矩阵全体 W，即 W =\n{B ∈Pn×n |AB =BA} 是 Pn×n 的一个子空间，记为 C(A)。 (2) 当 A=E 时，求 C(A)。 (3) 当 A=\n1 0 0 ⋯ 0\n0 2 0 ⋯ 0\n0 0 3 ⋯ 0\n时，求 C(A) 的维数和一组基。\n⋮ ⋮ ⋮ ⋮ ⋮\n0 0 0 ⋯ n",
      "type": "选择题",
      "topics": [
        "子空间",
        "与固定矩阵可交换的矩阵构成子空间"
      ],
      "difficulty": 2,
      "tags": [
        "陈维新",
        "习题精选",
        "4.5"
      ],
      "right_answer": "A",
      "key_points": [],
      "solutions": [
        {
          "name": "精选解析",
          "steps": [
            "（1）C(A)={B :AB =BA} 含零矩阵。若 AB =BA,AD =DA，则\nA(kB+tD)=kAB+tAD =(kB+tD)A,\n所以对线性组合封闭，是 Pn×n 的子空间。\n（3）A=diag(1,2,…,n)，由习题3.1-4，AB =BA 当且仅当 B 对角。于是\nC(A)=L(E ,E ,…,E ), dimC(A)=n.\n11 22 nn\n这些矩阵显然彼此无关，所以给出的生成组正是基。"
          ]
        }
      ],
      "pitfalls": [],
      "related": [],
      "added": "2026-10-21"
