      "tags": [
        "陈维新",
        "习题精选",
        "4.9"
      ],
      "right_answer": "对任意 f， DT(f)=(xf)′ =f +xf′, TD(f)=xf′, 所以 DT −TD =I。 若误把空间限制成固定次数上界，乘 x 可能越出该空间；本题使用的是全体多项式。",
      "key_points": [],
      "solutions": [
        {
          "name": "精选解析",
          "steps": [
            "在全体多项式空间上，D(f)=f′，T(f)=xf，两者都线性。对任意 f，\nDT(f)=(xf)′ =f +xf′, TD(f)=xf′,\n所以 DT −TD =I。若误把空间限制成固定次数上界，乘 x 可能越出该空间；本题使用的是全体多项式。"
          ]
        }
      ],
