      "statement": "设矩阵 A 与 B 相似，其中 A= 2 4 −2 ，B = 0 2 0 。 (1) 求 a,b 的值； (2) 求可逆矩\n−3 −3 a 0 0 b\n阵 P，使 P−1AP =B。",
