      "section": "§6.5  二次型的正定性",
      "statement": "设 A 是 n 阶正定矩阵,α 1 ,α 2 ,⋯ ,α n 均为 n 元非零的实的列向量,且满足 α i T Aα j =0 (i≠j; i,j =\n1,2,⋯ ,n). 证明: α 1 ,α 2 ,⋯ ,α n 线性无关.",
