      "section": "§1.1  线性方程组的形式及相关概念",
      "statement": "证明：对任意 n+1 个数 a 0 ,a 1 ,⋯ ,a n 和任意点 x=x 0 ，存在着 n 次多项式 f(x)，使得\nf(i)(x\n0\n)=a\ni\n, i=0,1,2,⋯ ,n。",
