      "section": "§1.1  线性方程组的形式及相关概念",
      "statement": "问 a,b,c 满足什么条件时，线性方程组 ax+by+cz =a2+b2+c2, 有惟一解，并求之。\n⎨\nbcx+acy+abz =3abc\n⎩",
