      "chapter": "第1章 线性方程组的求解",
      "section": "§1.1  线性方程组的形式及相关概念",
      "statement": "平面上 4 点 M (x ,y ),M (x ,y ),M (x ,y ),M (x ,y ) 在同一圆上的充要条件是什么？\n1 1 1 2 2 2 3 3 3 4 4 4",
