      "chapter": "第8章 欧氏空间",
      "section": "§8.2  标准正交基",
      "content": "",
      "formulas": [],
      "tips": [
        "插值：设未知系数，用函数值或导数值列线性方程组。",
        "流量与配料：先写守恒等式，再补充非负和容量约束。",
        "分块消元：使用 Schur 补 $D-CA^{-1}B$ 时不能交换矩阵乘法次序。",
        "最小二乘：解 $A^TAX=A^Tb$，并用 $A^Tr=0$ 检查残差。",
        "附录三、四、五的练习均按当前章节归类；附录一、二、六没有独立习题组。"
      ],
